import React from "react";

const SmallCard = ({ image, title, link }) => {
  return (
    <div className="flex flex-col items-center hover:scale-105 transition transform hover:shadow-lg p-4 rounded-lg border border-gray-200 bg-white">
      <img src={image} alt={title} className="w-40 h-40 object-cover rounded-lg shadow-md" />
      <a href={link} target="_blank" rel="noopener noreferrer" className="text-[#3366cc] text-xs hover:text-[#003399] mt-3 font-medium transition-colors">
        {title}
      </a>
    </div>
  );
};

export default SmallCard;
